        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Ensure caddress has code to allow a successful low-level call
        // The bug is about return value, not about revert, so we use a helper that will successfully handle the call and return true
        vm.assume(caddress != address(0));
        bool success;
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            success = true;
            assertTrue(result);
        } catch {
            success = false;
            // If it reverts, the property is vacuously true (not a case where both complete with different values)
        }
    }
}
// Helper that accepts a call to the transferFrom selector and returns true
contract TransferFromMock {
    fallback() external payable returns (bytes memory) {
        // Validate selector is transferFrom
        bytes4 selector = bytes4(msg.data);
        bytes4 expectedSelector = bytes4(keccak256("transferFrom(address,address,uint256)"));
        require(selector == expectedSelector, "Wrong function");
        // Return true as expected by the caller
        return abi.encode(true);
    }
}

