// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // Ensure arrays are non-empty and lengths match
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // Bound array length to avoid excessive loops
        vm.assume(_tos.length <= 10);
        // Bound each uint value to a reasonable range
        for(uint i=0; i<v.length; i++){
            v[i] = bound(v[i], 0, type(uint128).max);
        }
        // The adversarial callee must be a contract that does NOT revert on the low-level call,
        // so that both reference and bug complete without reverting.
        // We deploy a helper that accepts the call (no-op).
        AlwaysSuccess helper = new AlwaysSuccess();
        // Use the helper address instead of the fuzzed caddress to guarantee non-reverting completion.
        // This is required because a random fuzzed address is an EOA which always succeeds,
        // but to make the rule general we need a contract that behaves predictably.
        bool result = c.transfer(from, address(helper), _tos, v);
        assertTrue(result);
    }
}

contract AlwaysSuccess {
    fallback() external payable { }
}

